The seam is in place: `Worker` now takes an `ILoggerWrapper` via its constructor (defaulted to the real forwarder). My test constructs a Moq `Mock<ILoggerWrapper>`, INJECTS `.Object` through the constructor, drives `Run`, and verifies the logging call went through the injected seam.

<tool>submit_test(csharp)</tool>
```csharp
using Moq;
using Xunit;
using Microsoft.Extensions.Logging;

namespace Acme.Tests;

public class WorkerSeamTests
{
    [Fact]
    public void Run_GoesThroughInjectedSeam()
    {
        var logger = Mock.Of<ILogger>();
        var wrapper = new Mock<ILoggerWrapper>();
        var worker = new Worker(logger, wrapper.Object);
        worker.Run("job-1");
        wrapper.Verify(w => w.LogInformation("starting {Job}", "job-1"), Times.Once);
    }
}
